                    file_printable(sbuf, sizeof(sbuf), ms->ms_value.s)) == -1)
                        return -1;
                t = ms->offset;
                break;
        default:
                file_magerror(ms, "invalid m->type (%d) in mprint()", m->type);
                return -1;
        }
        return (int32_t)t;
